            if (webhook.Name != null)
                writer.WriteString("name", webhook.Name);
            else
                writer.WriteNull("name");

            if (webhook.Mode == null)
                writer.WriteNull("mode");
            else
            {
                var modeRawValue = WebhookModeValueConverter.ToJsonValue(webhook.Mode.Value);
                if (modeRawValue != null)
                    writer.WriteString("mode", modeRawValue);
                else
                    writer.WriteNull("mode");
            }

            if (webhook.LastFailureAt != null)
                writer.WriteString("last_failure_at", webhook.LastFailureAt.Value.ToString(LastFailureAtFormat));
            else
                writer.WriteNull("last_failure_at");

            if (webhook.DisabledAt != null)
                writer.WriteString("disabled_at", webhook.DisabledAt.Value.ToString(DisabledAtFormat));
            else
                writer.WriteNull("disabled_at");

            if (webhook.DisabledReason != null)
                writer.WriteString("disabled_reason", webhook.DisabledReason);
            else
                writer.WriteNull("disabled_reason");

            if (webhook.Secret != null)
                writer.WriteString("secret", webhook.Secret);
            else
                writer.WriteNull("secret");
        }
    }
}
